select MIN(f.id) as display_id, f.phone as phone, MAX(f.task_id) as task_id, COALESCE(NULLIF(TRIM(MAX(f.task_id)), ''), CONCAT('__id_', MIN(f.id))) as batch_key, MAX(f.query_type) as query_type, MAX(f.create_time) as query_time, COUNT(*) as platform_count,
SUM( CASE WHEN f.results IS NOT NULL AND TRIM(f.results) != '' AND LOWER(f.results) LIKE '%yes%' THEN 1 ELSE 0 END ) as marked_platform_count, GROUP_CONCAT(f.id ORDER BY f.id SEPARATOR ',') as member_ids from ( select uaqr.id, uaqr.phone, uaqr.task_id, uaqr.query_type, uaqr.create_time, uaqr.results from user_api_query_record uaqr
) f group by f.phone, COALESCE(NULLIF(TRIM(f.task_id), ''), CONCAT('__id_', f.id)) order by MAX(f.create_time) desc



    and uaqr.phone = #{phone}
     and uaqr.user_id = #{userId}


            and uaqr.id = CAST(SUBSTRING(#{batchKey}, 6) AS UNSIGNED)


            and uaqr.task_id = #{batchKey}


     and uaqr.create_by = #{createBy}

order by uaqr.platform_id asc, uaqr.id asc



     and uaqr.query_type = #{queryType}
     and uaqr.platform_id = #{platformId}
     and uaqr.platform_name = #{platformName}
     and uaqr.request_status = #{requestStatus}
     and uaqr.request_time = #{requestTime}
     and uaqr.user_id = #{userId}
     and uaqr.request_params = #{requestParams}
     and uaqr.response_result = #{responseResult}

        and (
            uaqr.ip_addr = #{ipAddr}
            or ((uaqr.ip_addr is null or uaqr.ip_addr = '') and uaqr.create_by like concat('%free-ip-', #{ipAddr}, '%'))
        )

     and uaqr.create_by like concat('%', #{createBy}, '%')
     and uaqr.task_id = #{taskId}
     and uaqr.phone = #{phone}

        and (
            uaqr.device_id = #{deviceId}
            or ((uaqr.device_id is null or uaqr.device_id = '') and uaqr.request_params like concat('%deviceId=', #{deviceId}, '%'))
        )



            and (
                (uaqr.device_source is null or uaqr.device_source = '' or uaqr.device_source = 'UNKNOWN')
                and uaqr.request_params not like '%deviceSource=%'
            )


            and (
                uaqr.device_source = #{deviceSource}
                or ((uaqr.device_source is null or uaqr.device_source = '') and uaqr.request_params like concat('%deviceSource=', #{deviceSource}, '%'))
            )




            and (
                (uaqr.source_type is null or uaqr.source_type = '' or uaqr.source_type = 'UNKNOWN')
                and uaqr.request_params not like '%sourceType=%'
            )


            and (
                uaqr.source_type = #{sourceType}
                or ((uaqr.source_type is null or uaqr.source_type = '') and uaqr.request_params like concat('%sourceType=', #{sourceType}, '%'))
            )



        and uaqr.create_time >= #{params.beginTime}


        and uaqr.create_time <= concat(#{params.endTime}, ' 23:59:59')


order by create_time desc

select
    DATE_FORMAT(uaqr.create_time, '%Y-%m-%d') as statDate,
    uaqr.request_status as requestStatus,
    uaqr.request_time as requestTime,
    COALESCE(NULLIF(uaqr.source_type, ''), 'UNKNOWN') as sourceType,
    COALESCE(NULLIF(uaqr.error_code, ''), '') as errorCode
from user_api_query_record uaqr

     and uaqr.query_type = #{queryType}
     and uaqr.platform_name = #{platformName}
     and uaqr.request_status = #{requestStatus}
     and uaqr.task_id = #{taskId}
     and uaqr.phone = #{phone}

        and (
            uaqr.ip_addr = #{ipAddr}
            or ((uaqr.ip_addr is null or uaqr.ip_addr = '') and uaqr.create_by like concat('%free-ip-', #{ipAddr}, '%'))
        )


        and (
            uaqr.device_id = #{deviceId}
            or ((uaqr.device_id is null or uaqr.device_id = '') and uaqr.request_params like concat('%deviceId=', #{deviceId}, '%'))
        )



            and (
                (uaqr.device_source is null or uaqr.device_source = '' or uaqr.device_source = 'UNKNOWN')
                and uaqr.request_params not like '%deviceSource=%'
            )


            and (
                uaqr.device_source = #{deviceSource}
                or ((uaqr.device_source is null or uaqr.device_source = '') and uaqr.request_params like concat('%deviceSource=', #{deviceSource}, '%'))
            )




            and (
                (uaqr.source_type is null or uaqr.source_type = '' or uaqr.source_type = 'UNKNOWN')
                and uaqr.request_params not like '%sourceType=%'
            )


            and (
                uaqr.source_type = #{sourceType}
                or ((uaqr.source_type is null or uaqr.source_type = '') and uaqr.request_params like concat('%sourceType=', #{sourceType}, '%'))
            )



        and uaqr.create_time >= #{params.beginTime}


        and uaqr.create_time <= concat(#{params.endTime}, ' 23:59:59')


order by uaqr.create_time asc

