update user_api_query_record
query_type = #{queryType}, request_status = #{requestStatus}, request_time = #{requestTime}, user_id = #{userId}, phone = #{phone}, source_type = #{sourceType}, device_id = #{deviceId}, device_source = #{deviceSource}, used_before = #{usedBefore}, used_after = #{usedAfter}, limit_value = #{limitValue}, error_code = #{errorCode}, ip_addr = #{ipAddr}, request_params = #{requestParams}, response_result = #{responseResult}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where user_api_query_record.id = #{id}
